<?php
$page_title='Users'; require_once __DIR__.'/../../config/database.php'; require_once __DIR__.'/../../config/session.php'; require_once __DIR__.'/../../config/functions.php'; require_once __DIR__.'/../../config/auth.php'; requireAdmin(); if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['id']??0);$active=(int)($_POST['is_active']??0);if($id&&$id!==getUserId()){$stmt=$pdo->prepare('UPDATE users SET is_active=? WHERE id=?');$stmt->execute([$active,$id]);}} $users=$pdo->query('SELECT id,full_name,email,role,is_active,created_at FROM users ORDER BY created_at DESC')->fetchAll();
?>
<?php include __DIR__.'/../includes/header.php'; ?><div class="admin-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><main class="admin-main"><div class="admin-topbar"><div><h1 class="admin-title">Users</h1><p class="admin-subtitle">Manage account access across fresher, mentor, and admin roles.</p></div></div><div class="admin-card admin-table-wrap"><table class="admin-table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Created</th><th>Access</th><th>Action</th></tr></thead><tbody><?php foreach($users as $user): ?><tr><td><?php echo htmlspecialchars($user['full_name']); ?></td><td><?php echo htmlspecialchars($user['email']); ?></td><td><?php echo ucfirst($user['role']); ?></td><td><?php echo htmlspecialchars(date('M d, Y',strtotime($user['created_at']))); ?></td><td><span class="badge bg-<?php echo $user['is_active']?'success':'secondary'; ?>"><?php echo $user['is_active']?'Active':'Disabled'; ?></span></td><td><?php if($user['id']!==getUserId()): ?><form method="POST"><input type="hidden" name="id" value="<?php echo $user['id']; ?>"><input type="hidden" name="is_active" value="<?php echo $user['is_active']?0:1; ?>"><button class="btn btn-sm btn-outline-primary"><?php echo $user['is_active']?'Disable':'Enable'; ?></button></form><?php else: ?><small class="text-muted">Current account</small><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></main></div><?php include __DIR__.'/../includes/footer.php'; ?>
